selector_to_html = {"a[href=\"Straight.html#pyskyfire.ducts.path.Straight\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Straight\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Straight</span></span></dt><dd><p>Distributed straight-pipe friction between two adjacent stations.</p></dd>", "a[href=\"PathStation.html#pyskyfire.ducts.path.PathStation\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.PathStation\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PathStation</span></span></dt><dd><p>A physical centerline station shared by flow components.</p></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.ducts.path.generate_path_stations\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.generate_path_stations\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">generate_path_stations</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nodes</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">Sequence</span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"PathNode.html#pyskyfire.ducts.path.PathNode\" title=\"pyskyfire.ducts.path.PathNode\"><span class=\"pre\">PathNode</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"PathStation.html#pyskyfire.ducts.path.PathStation\" title=\"pyskyfire.ducts.path.PathStation\"><span class=\"pre\">PathStation</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">...</span></span><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"Straight.html#pyskyfire.ducts.path.Straight\" title=\"pyskyfire.ducts.path.Straight\"><span class=\"pre\">Straight</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference internal\" href=\"Continuous.html#pyskyfire.ducts.path.Continuous\" title=\"pyskyfire.ducts.path.Continuous\"><span class=\"pre\">Continuous</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference internal\" href=\"RoundedBend.html#pyskyfire.ducts.path.RoundedBend\" title=\"pyskyfire.ducts.path.RoundedBend\"><span class=\"pre\">RoundedBend</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">...</span></span><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">]</span></span></span></span></dt><dd><p>Resolve control vertices into physical stations and connections.</p><p>Interior direction changes must state their interpretation explicitly with\n<a class=\"reference internal\" href=\"RoundedBend.html#pyskyfire.ducts.path.RoundedBend\" title=\"pyskyfire.ducts.path.RoundedBend\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">RoundedBend</span></code></a> or <a class=\"reference internal\" href=\"Continuous.html#pyskyfire.ducts.path.Continuous\" title=\"pyskyfire.ducts.path.Continuous\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Continuous</span></code></a>. Rounded bends become one\nlumped connection between tangent points. Continuous bends become one\nconnection carrying the exact arc length, center and normal.</p></dd>", "a[href=\"RoundedBend.html#pyskyfire.ducts.path.RoundedBend\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.RoundedBend\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RoundedBend</span></span></dt><dd><p>A complete lumped rounded-bend loss between adjacent stations.</p></dd>", "a[href=\"PathPlacement.html#pyskyfire.ducts.path.PathPlacement\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.PathPlacement\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PathPlacement</span></span></dt><dd><p>Place the first path station and establish its section roll.</p><p>The rotation maps template coordinates into assembly coordinates. The\ninitial floor direction is expressed in assembly coordinates, points from\nthe passage centroid toward its floor, and is projected perpendicular to\nthe starting tangent. Frame columns are (floor-to-roof, lateral, tangent).\nAll subsequent section orientations use minimal-rotation transport.</p></dd>", "a[href=\"#pyskyfire.ducts.path.rotation_about_axis\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.rotation_about_axis\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">rotation_about_axis</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axis</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return a proper 3x3 rotation; <code class=\"docutils literal notranslate\"><span class=\"pre\">angle</span></code> is in radians.</p></dd>", "a[href=\"#module-pyskyfire.ducts.path\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.path<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.path\" title=\"Link to this heading\">\u00b6</a></h1><p>Shared centerline construction, rigid placement, and transported frames.</p><p>Paths contain geometry only. Flow areas and fluid states belong to components.\nAll vectors use Cartesian coordinates and all angles are radians.</p>", "a[href=\"PathNode.html#pyskyfire.ducts.path.PathNode\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.PathNode\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PathNode</span></span></dt><dd><p>Human-friendly route vertex consumed by <code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">generate_path_stations()</span></code>.</p></dd>", "a[href=\"Path.html#pyskyfire.ducts.path.Path\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Path</span></span></dt><dd><p>Resolved stations and connections in order from inlet to outlet.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">s</span></code> is true arc length [m]. Geometry carries no bore diameter or state.\nUse <a class=\"reference internal\" href=\"#pyskyfire.ducts.path.Path.refined\" title=\"pyskyfire.ducts.path.Path.refined\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">refined()</span></code></a> to choose the thermal/flow integration resolution.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"Continuous.html#pyskyfire.ducts.path.Continuous\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Continuous\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Continuous</span></span></dt><dd><p>A locally resolved continuous-curvature connection.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code> is the exact centerline radius when known. If omitted on a\nmanually supplied layout, <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Path</span></code> estimates it transparently from\nneighboring station triples using Menger curvature. Attached to a\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">PathNode</span></code>, it rounds that corner with a circular arc of <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code>,\nwhich the generator emits as one connection carrying its exact arc\n<code class=\"docutils literal notranslate\"><span class=\"pre\">length</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">center</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">normal</span></code>. A constant-section arc needs no\nfurther stations; <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code> adds them where its section varies.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
